  cstr_drop(&fileNm);
  fileNm = cstr_from_fmt("%s-%s_source_bgk_M1dot_%d.gkyl", app->name, gks->info.name, frame);
  gkyl_comm_array_write(app->comm, &app->grid, &app->local, mt, src->M1dot_host, fileNm.str);
