  fileNm = cstr_from_fmt("%s-%s_source_bgk_M2dot_%d.gkyl", app->name, gks->info.name, frame);
  gkyl_comm_array_write(app->comm, &app->grid, &app->local, mt, src->M2dot_host, fileNm.str);
  cstr_drop(&fileNm);

  gkyl_msgpack_data_release(mt);
}

