  double *arrData = arr->data;
  for (unsigned i = 0; i < arr->size; ++i) {
    arrData[i] = (i + 0.5) * 0.1;
  }

  // copy arr data to device data in arr_cu
  gkyl_array_copy(arr_cu, arr);

  // create new struct arr_cu_cl that is a clone of arr_cu
