  for (unsigned i = 0; i < arr->size; ++i) {
    TEST_CHECK(arrData[i] == -(i + 0.5) * 0.1);
  }

  // release all data
  gkyl_array_release(arr_cu_cl);
  gkyl_array_release(arr);
  gkyl_array_release(arr_cu);
}

